-- Telemetry of an app that calls language models: every call (who, which feature, which model, tokens, latency, cost) and the feedback some of them got.
-- Made by scripts/dev/make-sql-data.py: do not edit by hand.

CREATE TABLE models (
  name TEXT PRIMARY KEY,
  input_per_1k REAL NOT NULL,  -- dollars per 1,000 prompt tokens
  output_per_1k REAL NOT NULL  -- dollars per 1,000 completion tokens
);

CREATE TABLE llm_calls (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL,
  feature TEXT NOT NULL,  -- chat, search, summarize or agent
  model TEXT NOT NULL REFERENCES models(name),
  prompt_tokens INTEGER NOT NULL,
  completion_tokens INTEGER NOT NULL,
  latency_ms INTEGER NOT NULL,
  status TEXT NOT NULL,  -- ok, error or timeout
  cost_usd REAL NOT NULL,  -- 0 when the call failed
  created_at TEXT NOT NULL  -- YYYY-MM-DD HH:MM:SS
);

CREATE TABLE feedback (
  call_id INTEGER NOT NULL REFERENCES llm_calls(id),
  rating INTEGER NOT NULL,  -- 1 for a thumbs up, -1 for a thumbs down
  comment TEXT
);
